export type ParsedSettleMarketInstruction<
  TProgram extends string = typeof OUTCOME_TOKENS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    settler: TAccountMetas[0];
    /** Funds the vault's rent. */
    payer: TAccountMetas[1];
    config: TAccountMetas[2];
    market: TAccountMetas[3];
    /**
     * program created. Left untyped so that a market without its mints is reported as
     * such, not as an account that does not exist.
     */
    yesMint: TAccountMetas[4];
    noMint: TAccountMetas[5];
    /**
     * account here; an `init` constraint would run before the checks on `market` and
     * report a settled market as a System program error.
     */
    vault: TAccountMetas[6];
    funderStable: TAccountMetas[7];
    stableMint: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: SettleMarketInstructionData;
};

export function parseSettleMarketInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleMarketInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      settler: getNextAccount(),
      payer: getNextAccount(),
      config: getNextAccount(),
      market: getNextAccount(),
      yesMint: getNextAccount(),
      noMint: getNextAccount(),
      vault: getNextAccount(),
      funderStable: getNextAccount(),
      stableMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSettleMarketInstructionDataDecoder().decode(instruction.data),
  };
}
